; z80dasm 1.1.6
; command line: z80dasm -g 0x0000 -o assembly/189733_fixed.asm roms/189733_fixed.rom

	org	00000h

	ld sp,0cc66h
	jp reset_entry

; ROM identification, short dispatch entries and pointer records (data, not code).
	defb 044h,005h,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh
	defb 038h,000h,038h,000h,038h,000h,038h,000h
	defw 0947h,0984h,0966h,0987h
	defb 016h,028h,063h,029h,020h,031h,039h,039h,032h,020h,046h,044h
	defb 050h,02ch,020h,049h,06eh,063h,020h,04fh,037h,033h,033h,0ffh
	jp 03dceh

; Interrupt dispatch table and unused/reset vector slots.
	defs 5,0ffh
	defw 0852h,088fh,0871h,0892h,075dh,079ah,077ch,079dh
	defb 038h,000h,038h,000h,038h,000h,0fah,003h
	defs 14,0ffh

video_interrupt_handler:
	push af	
	push hl	
	in a,(051h)
	and 00ah
	cp 002h
	jr nz,$+37
	ld hl,(0c360h)
	ld a,(hl)	
	or a	
	jr z,$+24
	out (05dh),a
	inc hl	
	ld a,(hl)	
	out (056h),a
	inc hl	
	ld a,(hl)	
	out (05ah),a
	inc hl	
	ld (0c360h),hl
	ld a,00ah
	out (05bh),a
	pop hl	
	pop af	
	retn

; Second ASIC interrupt path: wait for the programmed raster condition,
; acknowledge it and restore the pending cursor/display registers.
video_status_wait:
	ld a,00eh
	out (059h),a
	jr $-12
	bit 1,a
	jr nz,$-16
	in a,(051h)
	bit 2,a
	jr z,$+28
	ld a,(0c002h)
	bit 3,a
	call z,002c5h
	ld a,00ch
	out (059h),a
	call 000dah
	ld hl,0c001h
	set 2,(hl)
	ld a,004h
	out (05bh),a
	in a,(051h)
	bit 0,a
	jr z,$+6
	ld a,001h
	out (05bh),a
	ld a,(0c01ah)
	inc a	
	ld (0c01ah),a
	cp 001h
	jr nz,$+10
	ld a,087h
	out (073h),a
	ld a,001h
	out (073h),a
	ld a,008h
	out (05bh),a
	pop hl	
	pop af	
	retn

; Restore the cursor and display-list registers from the active record.
restore_video_display_state:
	ld hl,0c65ah
	ld a,(hl)	
	out (05dh),a
	inc hl	
	ld a,(hl)	
	out (056h),a
	inc hl	
	ld a,(hl)	
	out (05ah),a
	inc hl	
	ld (0c360h),hl
	ld a,(0c362h)
	out (057h),a
	ret	

; Reset entry.  Initialize the stack and IM2 vectors, clear working RAM,
; detect memory, and bring up the ASIC and board peripherals.
reset_entry:
	di	
	ld a,004h
	ld c,0fah
	ld b,030h
	djnz $+0
	dec c	
	jr nz,$-5
	dec a	
	jr nz,$-10
	call reset_video_asic
	di	
	call 0718eh
	ld sp,0cc66h
	ld iy,0c080h
	ld hl,0003bh
	ld a,h	
	ld i,a
	im 2
	ld hl,0c04ch
	ld de,0c000h
	call clear_memory_range
	ld hl,0c360h
	ld de,0c122h
	call clear_memory_range
	call initialize_board_io
	call 03319h
	call 072beh
